Documentation = {
    init: async function(app, container) {
        app = app || session.app;
        container = container || $(".component[name=Documentation]");
        $("[name=tabs]", container).kendoTabStrip({ animation: { open: { effects: "fadeIn" } } });

        var businessDocs = await loadComponent($(".tab[name=businessDocs]", container), "FolderManagement");
        businessDocs.init(app, $(".component[name=FolderManagement]", $(".tab[name=businessDocs]", container)), { Id: '6A23BDC8-2CA7-4B91-A62F-08D7725C8272', Path: 'documentation/business docs', Name: 'Business Requirements' }, true);

        var technicalDocs = await loadComponent($(".tab[name=technicalDocs]", container), "FolderManagement");
        technicalDocs.init(app, $(".component[name=FolderManagement]", $(".tab[name=technicalDocs]", container)), { Id: '487DB4A6-D50B-49F6-A630-08D7725C8272', Path: 'documentation/technical docs', Name: 'Technical Requirements' }, true);
    }
};
